    16: { m: ["Adding, {S} = {x1} + {x2} + {x3} = ({a} + {b} + {c})/2 = 45; then {x3} = {S} − {a} = 25, {x1} = {S} − {b} = 15, {x2} = {S} − {c} = 5.", "Positive if {S} exceeds each datum: the <em>diorismos</em>."] },
